import type { DeepReadonly } from "@btst/stack/plugins/api";
export const feedbackStatuses = [
	"under_review",
	"planned",
	"in_progress",
	"shipped",
	"closed",
] as const;
/** A feature request’s review or delivery status. */
export type FeedbackStatus = (typeof feedbackStatuses)[number];

/** Public feature request with ISO timestamps and the current user’s vote state. */
export type FeedbackPost = {
	id: string;
	slug: string;
	title: string;
	body: string;
	category: string;
	status: FeedbackStatus;
	authorId: string;
	kanbanTaskId: string | null;
	voteCount: number;
	isVoted: boolean;
	createdAt: string;
	updatedAt: string;
};
/** Stored feature request, including the transaction lock marker. */
export interface FeedbackPostRecord
	extends Omit<FeedbackPost, "isVoted" | "createdAt" | "updatedAt"> {
	lockVersion: string;
	createdAt: Date;
	updatedAt: Date;
}
/** Stored vote; the unique key encodes its post and user IDs. */
export interface FeedbackVote {
	id: string;
	key: string;
	postId: string;
	userId: string;
	createdAt: Date;
}
/** Published release note with its linked feature requests. */
export type ChangelogEntry = {
	id: string;
	title: string;
	body: string;
	publishedAt: string;
	createdAt: string;
	posts: FeedbackPost[];
};
/** Stored release note with serialized request IDs and native dates. */
export interface ChangelogEntryRecord
	extends Omit<ChangelogEntry, "posts" | "publishedAt" | "createdAt"> {
	postIds: string;
	publishedAt: Date;
	createdAt: Date;
}
/** Content accepted when submitting a feature request. */
export interface CreateFeedbackPostInput {
	title: string;
	body: string;
	category?: string;
}
/** Release note content and IDs of shipped requests to link. */
export interface CreateChangelogEntryInput {
	title: string;
	body: string;
	postIds: string[];
	publishedAt?: string;
}
/** Category, status and pagination filters for the voting board. */
export interface FeedbackListParams {
	category?: string;
	status?: FeedbackStatus;
	limit?: number;
	offset?: number;
}
/** Requests grouped into the public delivery columns. */
export type FeedbackRoadmap = {
	planned: FeedbackPost[];
	in_progress: FeedbackPost[];
	shipped: FeedbackPost[];
};

/** Optional application bridge; resolve tasks through the request's authorized Kanban operations. */
export interface FeedbackKanbanBridge {
	/** Return the matching task from an authorized board read, or null when absent. */
	getTask: (context: {
		id: string;
		boardId: string;
		request?: Request;
	}) => Promise<{ id: string } | null>;
}
/** Hooks run after a successful, authorized status update has committed. */
export interface FeedbackBackendHooks {
	onAfterUpdatePostStatus?: (
		post: DeepReadonly<FeedbackPost>,
		previousStatus: FeedbackStatus,
	) => void | Promise<void>;
}
/** Optional Feedback integrations; no companion plugin is imported by Feedback. */
export interface FeedbackBackendOptions {
	hooks?: FeedbackBackendHooks;
	/** Enables task linking after validating the target through the application. */
	kanban?: FeedbackKanbanBridge;
}
/** Link an existing task on a board, or clear the current task link. */
export interface LinkFeedbackKanbanTaskInput {
	id: string;
	kanbanTaskId: string | null;
	boardId?: string;
}

import { z } from "zod";
import { feedbackStatuses } from "./types";

export const feedbackStatusSchema = z.enum(feedbackStatuses);
export const idSchema = z.object({ id: z.string().min(1).max(200) });
export const listFeedbackPostsSchema = z.object({
	category: z.string().trim().min(1).max(100).optional(),
	status: feedbackStatusSchema.optional(),
	limit: z.coerce.number().int().min(1).max(100).default(50),
	offset: z.coerce.number().int().min(0).default(0),
});
export const createFeedbackPostSchema = z.object({
	title: z.string().trim().min(1).max(200),
	body: z.string().trim().min(1).max(20000),
	category: z.string().trim().min(1).max(100).default("General"),
});
export const updateFeedbackStatusSchema = z.object({
	status: feedbackStatusSchema,
});
export const listChangelogSchema = z.object({
	limit: z.coerce.number().int().min(1).max(100).default(50),
	offset: z.coerce.number().int().min(0).default(0),
});
export const createChangelogEntrySchema = z.object({
	title: z.string().trim().min(1).max(200),
	body: z.string().trim().min(1).max(50000),
	postIds: z
		.array(z.string().min(1).max(200))
		.max(100)
		.transform((ids) => [...new Set(ids)]),
	publishedAt: z.iso.datetime().optional(),
});

export const linkFeedbackKanbanTaskSchema = z
	.object({
		kanbanTaskId: z.string().min(1).max(200).nullable(),
		boardId: z.string().min(1).max(200).optional(),
	})
	.refine((input) => input.kanbanTaskId === null || Boolean(input.boardId), {
		path: ["boardId"],
		message: "A board is required to validate the linked task",
	});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";
import { feedbackStatusSchema } from "./schemas";

const postFacts = z.object({
	postId: z.string(),
	status: feedbackStatusSchema,
	authorId: z.string(),
});
export const feedbackPermissions = definePermissions("feedback", {
	post: {
		read: permission(
			z.discriminatedUnion("scope", [
				z.object({ scope: z.literal("collection") }),
				z.object({
					scope: z.literal("record"),
					postId: z.string(),
					slug: z.string(),
				}),
			]),
		),
		create: permission(),
		vote: permission(postFacts),
		updateStatus: permission(postFacts),
		linkKanbanTask: permission(postFacts),
	},
	changelog: { read: permission(), create: permission() },
});

"use client";

import { lazy } from "react";
import {
	ComposedRoute,
	PermissionRouteAccess,
} from "@btst/stack/client/components";
import { useFeedbackPost } from "@btst/plugin-feedback/client/hooks";
import { feedbackPermissions } from "../../permissions";
import { FeedbackError, FeedbackLoading, FeedbackNotFound } from "./shared";

const Board = lazy(() =>
	import("./pages/feedback-page.internal").then((m) => ({
		default: m.FeedbackBoardPage,
	})),
);
const Post = lazy(() =>
	import("./pages/post-page.internal").then((m) => ({
		default: m.FeedbackPostPage,
	})),
);
const Roadmap = lazy(() =>
	import("./pages/roadmap-page.internal").then((m) => ({
		default: m.FeedbackRoadmapPage,
	})),
);
const Changelog = lazy(() =>
	import("./pages/changelog-page.internal").then((m) => ({
		default: m.FeedbackChangelogPage,
	})),
);
const boundary = {
	ErrorComponent: FeedbackError,
	LoadingComponent: FeedbackLoading,
	NotFoundComponent: FeedbackNotFound,
	onError: (error: Error) => console.error("[btst/feedback]", error),
};

export function FeedbackPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/feedback"
			permission={feedbackPermissions.post.read({ scope: "collection" })}
			PageComponent={Board}
		/>
	);
}
function AuthorizedPost({ slug }: { slug: string }) {
	const { data: post } = useFeedbackPost(slug);
	return (
		<PermissionRouteAccess
			permission={feedbackPermissions.post.read({
				scope: "record",
				postId: post.id,
				slug: post.slug,
			})}
			LoadingComponent={FeedbackLoading}
		>
			<Post slug={slug} />
		</PermissionRouteAccess>
	);
}
export function FeedbackPostPageComponent({ slug }: { slug: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/feedback/${slug}`}
			PageComponent={AuthorizedPost}
			props={{ slug }}
		/>
	);
}
export function FeedbackRoadmapPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/feedback/roadmap"
			permission={feedbackPermissions.post.read({ scope: "collection" })}
			PageComponent={Roadmap}
		/>
	);
}
export function FeedbackChangelogPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/feedback/changelog"
			permission={feedbackPermissions.changelog.read()}
			PageComponent={Changelog}
		/>
	);
}

"use client";

import { useId, useState, type FormEvent } from "react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { feedbackPermissions } from "../../../permissions";
import {
	useCreateChangelogEntry,
	useFeedbackChangelog,
	useFeedbackPosts,
} from "@btst/plugin-feedback/client/hooks";
import { FEEDBACK_PLUGIN_ID } from "../../constants";
import { FeedbackPage, Field, Pagination } from "../shared";

function ChangelogEditor({ onPublished }: { onPublished: () => void }) {
	const id = useId();
	const [offset, setOffset] = useState(0);
	const [selected, setSelected] = useState<string[]>([]);
	const [error, setError] = useState("");
	const { data: shipped } = useFeedbackPosts({
		status: "shipped",
		limit: 25,
		offset,
	});
	const create = useCreateChangelogEntry();
	const submit = async (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const fields = new FormData(event.currentTarget);
		setError("");
		try {
			await create.mutateAsync({
				title: String(fields.get("title")),
				body: String(fields.get("body")),
				postIds: selected,
			});
			onPublished();
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "Release could not be published.",
			);
		}
	};
	return (
		<form
			onSubmit={submit}
			className="space-y-4 rounded-lg border p-5"
			aria-label="Publish a release"
		>
			<Field id={`${id}-title`} label="Release title">
				<Input
					id={`${id}-title`}
					name="title"
					required
					maxLength={200}
					autoFocus
				/>
			</Field>
			<Field id={`${id}-body`} label="Release notes">
				<Textarea
					id={`${id}-body`}
					name="body"
					required
					maxLength={20000}
					rows={5}
				/>
			</Field>
			<fieldset className="space-y-3">
				<legend className="mb-3 text-sm font-medium">
					Linked shipped requests
				</legend>
				{shipped.items.length ? (
					shipped.items.map((post) => (
						<label
							key={post.id}
							className="flex min-h-11 items-center gap-3 text-sm"
						>
							<input
								type="checkbox"
								value={post.id}
								checked={selected.includes(post.id)}
								onChange={(event) =>
									setSelected((current) =>
										event.target.checked
											? [...current, post.id]
											: current.filter((postId) => postId !== post.id),
									)
								}
							/>
							{post.title}
						</label>
					))
				) : (
					<p className="text-sm text-muted-foreground">
						Ship a feature request to link it to a release.
					</p>
				)}
			</fieldset>
			<Pagination offset={offset} total={shipped.total} onChange={setOffset} />
			{error && (
				<p role="alert" className="text-destructive">
					{error}
				</p>
			)}
			<Button type="submit" disabled={create.isPending}>
				{create.isPending ? "Publishing…" : "Publish release"}
			</Button>
		</form>
	);
}

export function FeedbackChangelogPage() {
	const [offset, setOffset] = useState(0);
	const [editing, setEditing] = useState(false);
	const [message, setMessage] = useState("");
	const { data } = useFeedbackChangelog({ limit: 25, offset });
	const { Link, resolve } = usePluginSiteNavigation(FEEDBACK_PLUGIN_ID);
	return (
		<FeedbackPage title="Changelog">
			<div className="flex flex-wrap items-center justify-between gap-4">
				<p className="text-muted-foreground">
					Release notes and the requests behind each improvement.
				</p>
				<PermissionAccess permission={feedbackPermissions.changelog.create()}>
					<Button aria-expanded={editing} onClick={() => setEditing(!editing)}>
						{editing ? "Cancel release" : "Write a release"}
					</Button>
				</PermissionAccess>
			</div>
			{message && <p role="status">{message}</p>}
			{editing && (
				<PermissionAccess permission={feedbackPermissions.changelog.create()}>
					<ChangelogEditor
						onPublished={() => {
							setEditing(false);
							setMessage("Release published");
						}}
					/>
				</PermissionAccess>
			)}
			<div className="space-y-8">
				{data.items.length ? (
					data.items.map((entry) => (
						<article key={entry.id} className="space-y-4 rounded-lg border p-6">
							<time
								className="text-sm text-muted-foreground"
								dateTime={entry.publishedAt}
							>
								{entry.publishedAt.slice(0, 10)}
							</time>
							<h2 className="break-words text-2xl font-semibold">
								{entry.title}
							</h2>
							<p className="whitespace-pre-wrap break-words leading-7">
								{entry.body}
							</p>
							{entry.posts.length > 0 && (
								<div className="space-y-2">
									<h3 className="text-sm font-medium">Shipped requests</h3>
									<ul className="list-inside list-disc space-y-2">
										{entry.posts.map((post) => (
											<li key={post.id}>
												<Link
													href={
														resolve(`feedback/${encodeURIComponent(post.slug)}`)
															.href
													}
													className="rounded-sm underline focus-visible:outline-2 focus-visible:outline-ring"
												>
													{post.title}
												</Link>
											</li>
										))}
									</ul>
								</div>
							)}
						</article>
					))
				) : (
					<p className="py-8 text-muted-foreground">
						No releases published yet.
					</p>
				)}
			</div>
			<Pagination offset={offset} total={data.total} onChange={setOffset} />
		</FeedbackPage>
	);
}

"use client";

import { useId, useState, type FormEvent } from "react";
import { PermissionAccess } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { feedbackPermissions } from "../../../permissions";
import type { FeedbackStatus } from "../../../types";
import { useCreateFeedbackPost, useFeedbackPosts } from "@btst/plugin-feedback/client/hooks";
import { FeedbackPostCard } from "../post-card";
import {
	FeedbackPage,
	Field,
	Pagination,
	selectClass,
	statusLabels,
} from "../shared";

export function FeedbackBoardPage() {
	const id = useId();
	const [category, setCategory] = useState("");
	const [status, setStatus] = useState<FeedbackStatus | "">("");
	const [offset, setOffset] = useState(0);
	const [showForm, setShowForm] = useState(false);
	const [error, setError] = useState("");
	const [message, setMessage] = useState("");
	const { data } = useFeedbackPosts({
		category: category.trim() || undefined,
		status: status || undefined,
		limit: 25,
		offset,
	});
	const create = useCreateFeedbackPost();
	const submit = async (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const form = event.currentTarget;
		const fields = new FormData(form);
		setError("");
		setMessage("");
		try {
			await create.mutateAsync({
				title: String(fields.get("title")),
				body: String(fields.get("body")),
				category: String(fields.get("category") || "").trim() || undefined,
			});
			form.reset();
			setShowForm(false);
			setMessage("Feature request submitted");
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "Request could not be submitted.",
			);
		}
	};
	return (
		<FeedbackPage title="Feature requests">
			<div className="flex flex-wrap items-center justify-between gap-4">
				<p className="max-w-2xl text-muted-foreground">
					Share an idea and vote for the improvements you want to see.
				</p>
				<PermissionAccess permission={feedbackPermissions.post.create()}>
					<Button
						onClick={() => setShowForm(!showForm)}
						aria-expanded={showForm}
					>
						{showForm ? "Cancel request" : "Submit a request"}
					</Button>
				</PermissionAccess>
			</div>
			{message && <p role="status">{message}</p>}
			{showForm && (
				<PermissionAccess permission={feedbackPermissions.post.create()}>
					<form
						onSubmit={submit}
						className="space-y-4 rounded-lg border p-5"
						aria-label="Submit a feature request"
					>
						<Field id={`${id}-title`} label="Request title">
							<Input
								id={`${id}-title`}
								name="title"
								required
								maxLength={200}
								autoFocus
							/>
						</Field>
						<Field id={`${id}-body`} label="Description">
							<Textarea
								id={`${id}-body`}
								name="body"
								required
								maxLength={20000}
								rows={5}
							/>
						</Field>
						<Field id={`${id}-category`} label="Category">
							<Input id={`${id}-category`} name="category" maxLength={100} />
						</Field>
						{error && (
							<p role="alert" className="text-destructive">
								{error}
							</p>
						)}
						<Button type="submit" disabled={create.isPending}>
							{create.isPending ? "Submitting…" : "Submit request"}
						</Button>
					</form>
				</PermissionAccess>
			)}
			<div className="grid gap-4 sm:grid-cols-2">
				<Field id={`${id}-filter-category`} label="Filter by category">
					<Input
						id={`${id}-filter-category`}
						value={category}
						onChange={(event) => {
							setCategory(event.target.value);
							setOffset(0);
						}}
						placeholder="All categories"
					/>
				</Field>
				<Field id={`${id}-filter-status`} label="Filter by status">
					<select
						id={`${id}-filter-status`}
						className={selectClass}
						value={status}
						onChange={(event) => {
							setStatus(event.target.value as FeedbackStatus | "");
							setOffset(0);
						}}
					>
						<option value="">All statuses</option>
						{Object.entries(statusLabels).map(([value, label]) => (
							<option key={value} value={value}>
								{label}
							</option>
						))}
					</select>
				</Field>
			</div>
			<div className="space-y-4">
				{data.items.length ? (
					data.items.map((post) => (
						<FeedbackPostCard page="feedback" key={post.id} post={post} />
					))
				) : (
					<p className="py-8 text-muted-foreground">
						No feature requests match these filters.
					</p>
				)}
			</div>
			<Pagination offset={offset} total={data.total} onChange={setOffset} />
		</FeedbackPage>
	);
}

"use client";

import { useId, useState } from "react";
import { PermissionAccess, usePluginOverrides } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { feedbackPermissions } from "../../../permissions";
import type { FeedbackPost, FeedbackStatus } from "../../../types";
import { useFeedbackPost, useUpdateFeedbackStatus } from "@btst/plugin-feedback/client/hooks";
import { FEEDBACK_PLUGIN_ID } from "../../constants";
import type { FeedbackPluginOverrides } from "../../overrides";
import { FeedbackVoteButton } from "../post-card";
import {
	FeedbackPage,
	FeedbackStatusLabel,
	Field,
	selectClass,
	statusLabels,
} from "../shared";

function StatusEditor({ post }: { post: FeedbackPost }) {
	const id = useId();
	const [status, setStatus] = useState(post.status);
	const [error, setError] = useState("");
	const update = useUpdateFeedbackStatus();
	return (
		<form
			className="flex flex-wrap items-end gap-3 rounded-lg border p-4"
			onSubmit={async (event) => {
				event.preventDefault();
				setError("");
				try {
					await update.mutateAsync({ id: post.id, status });
				} catch (caught) {
					setError(
						caught instanceof Error
							? caught.message
							: "Status could not be updated.",
					);
				}
			}}
		>
			<Field id={id} label="Request status">
				<select
					id={id}
					className={selectClass}
					value={status}
					onChange={(event) => setStatus(event.target.value as FeedbackStatus)}
				>
					{Object.entries(statusLabels).map(([value, label]) => (
						<option key={value} value={value}>
							{label}
						</option>
					))}
				</select>
			</Field>
			<Button
				type="submit"
				disabled={update.isPending || status === post.status}
			>
				Update status
			</Button>
			{error && (
				<p role="alert" className="w-full text-destructive">
					{error}
				</p>
			)}
		</form>
	);
}

export function FeedbackPostPage({ slug }: { slug: string }) {
	const { data: post } = useFeedbackPost(slug);
	const overrides =
		usePluginOverrides<FeedbackPluginOverrides>(FEEDBACK_PLUGIN_ID);
	return (
		<FeedbackPage title={post.title}>
			<div className="flex flex-wrap items-center gap-4">
				<FeedbackVoteButton post={post} />
				<FeedbackStatusLabel status={post.status} />
				{post.category && (
					<span className="text-muted-foreground">{post.category}</span>
				)}
			</div>
			<p className="whitespace-pre-wrap break-words leading-7">{post.body}</p>
			<PermissionAccess
				permission={feedbackPermissions.post.updateStatus({
					postId: post.id,
					status: post.status,
					authorId: post.authorId,
				})}
			>
				<StatusEditor key={`${post.id}:${post.status}`} post={post} />
			</PermissionAccess>
			{overrides.kanbanTaskSlot && (
				<PermissionAccess
					permission={feedbackPermissions.post.linkKanbanTask({
						postId: post.id,
						status: post.status,
						authorId: post.authorId,
					})}
				>
					{overrides.kanbanTaskSlot(post)}
				</PermissionAccess>
			)}
			{overrides.postBottomSlot && <div>{overrides.postBottomSlot(post)}</div>}
		</FeedbackPage>
	);
}

"use client";

import { useFeedbackRoadmap } from "@btst/plugin-feedback/client/hooks";
import { FeedbackPostCard } from "../post-card";
import { FeedbackPage, statusLabels } from "../shared";

export function FeedbackRoadmapPage() {
	const { data } = useFeedbackRoadmap();
	return (
		<FeedbackPage title="Roadmap">
			<p className="text-muted-foreground">
				Follow requests from planning to release.
			</p>
			<div className="grid min-w-0 gap-6 lg:grid-cols-3">
				{(["planned", "in_progress", "shipped"] as const).map((status) => (
					<section
						key={status}
						className="min-w-0 space-y-4"
						aria-label={statusLabels[status]}
					>
						<h2 className="text-xl font-semibold">{statusLabels[status]}</h2>
						{data[status].length ? (
							data[status].map((post) => (
								<FeedbackPostCard
									page="feedbackRoadmap"
									key={post.id}
									post={post}
								/>
							))
						) : (
							<p className="rounded-lg border p-5 text-sm text-muted-foreground">
								No requests in this stage.
							</p>
						)}
					</section>
				))}
			</div>
		</FeedbackPage>
	);
}

"use client";

import { useState } from "react";
import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import type { FeedbackPost } from "../../types";
import { feedbackPermissions } from "../../permissions";
import { useToggleFeedbackVote } from "@btst/plugin-feedback/client/hooks";
import type { FeedbackPluginOverrides } from "../overrides";
import { FEEDBACK_PLUGIN_ID } from "../constants";
import { FeedbackStatusLabel } from "./shared";

export function FeedbackVoteButton({ post }: { post: FeedbackPost }) {
	const vote = useToggleFeedbackVote();
	const [error, setError] = useState("");
	return (
		<div className="space-y-1">
			<PermissionAccess
				permission={feedbackPermissions.post.vote({
					postId: post.id,
					status: post.status,
					authorId: post.authorId,
				})}
				fallback={
					<span className="text-sm text-muted-foreground">
						{post.voteCount} votes
					</span>
				}
			>
				<Button
					variant={post.isVoted ? "default" : "outline"}
					aria-pressed={post.isVoted}
					aria-label={`${post.isVoted ? "Remove vote for" : "Vote for"} ${post.title}`}
					disabled={vote.isPending}
					onClick={async () => {
						setError("");
						try {
							await vote.mutateAsync({ id: post.id });
						} catch (caught) {
							setError(
								caught instanceof Error
									? caught.message
									: "Vote could not be saved.",
							);
						}
					}}
				>
					{post.voteCount} {post.voteCount === 1 ? "vote" : "votes"}
				</Button>
			</PermissionAccess>
			{error && (
				<p role="alert" className="text-sm text-destructive">
					{error}
				</p>
			)}
		</div>
	);
}

export function FeedbackPostCard({
	page,
	post,
}: {
	page?: "feedback" | "feedbackRoadmap";
	post: FeedbackPost;
}) {
	const { pageOverrides } =
		usePluginOverrides<FeedbackPluginOverrides>(FEEDBACK_PLUGIN_ID);
	const Component = page ? pageOverrides?.[page]?.PostCard : undefined;
	return Component ? (
		<Component post={post} />
	) : (
		<DefaultFeedbackPostCard post={post} />
	);
}

function DefaultFeedbackPostCard({ post }: { post: FeedbackPost }) {
	const { Link, resolve } = usePluginSiteNavigation(FEEDBACK_PLUGIN_ID);
	return (
		<article
			className="flex min-w-0 flex-wrap items-start gap-4 rounded-lg border p-5"
			data-testid="feedback-post-card"
		>
			<FeedbackVoteButton post={post} />
			<div className="min-w-0 flex-1 space-y-3">
				<h2 className="break-words text-lg font-semibold">
					<Link
						href={resolve(`feedback/${encodeURIComponent(post.slug)}`).href}
						className="rounded-sm hover:underline focus-visible:outline-2 focus-visible:outline-ring"
					>
						{post.title}
					</Link>
				</h2>
				<p className="line-clamp-3 whitespace-pre-wrap break-words text-sm text-muted-foreground">
					{post.body}
				</p>
				<div className="flex flex-wrap items-center gap-3">
					<FeedbackStatusLabel status={post.status} />
					{post.category && (
						<span className="text-sm text-muted-foreground">
							{post.category}
						</span>
					)}
				</div>
			</div>
		</article>
	);
}

"use client";

